{
  "name": "opencode-statboard",
  "version": "2.10.19",
  "description": "Real-time dashboard for opencode token usage and cost statistics",
  "main": "server.js",
  "bin": {
    "opencode-dashboard": "server.js",
    "opencode-tui": "tui-dashboard.js"
  },
  "scripts": {
    "start": "node server.js",
    "tui": "node tui-dashboard.js",
    "tui:web": "node tui-dashboard.js --web",
    "both": "node tui-dashboard.js --both",
    "test": "node --check server.js && node --check check-lib.js && node --check pricing.js && node --check check-stats-verify.js && node --check check-trend-verify.js && node --check check-report-verify.js && node --check check-frontend-smoke.js && node --check tui-dashboard.js"
  },
  "keywords": [
    "opencode",
    "dashboard",
    "tokens",
    "usage",
    "statistics",
    "tui"
  ],
  "author": "thumb2086",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/thumb2086/opencode-usage-dashboard.git"
  },
  "dependencies": {
    "better-sqlite3": "^13.0.3",
    "blessed": "^0.1.81"
  }
}
